#include <iostream>
#include <vector>
#include <string>

struct Task {
    int id;
    std::string title;
    bool completed = false;
};

class TodoList {
    std::vector<Task> tasks;
    int nextId = 1;
public:
    void add(const std::string& title) {
        tasks.push_back({nextId++, title, false});
    }
    void display() const {
        for (const auto& t : tasks) {
            std::cout << "[" << (t.completed ? "X" : " ") << "] "
                      << t.id << ". " << t.title << "\n";
        }
    }
};

int main() {
    TodoList todo;
    todo.add("Setup C++ project");
    todo.add("Implement persistence");
    todo.display();
    return 0;
}

