#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

struct Contact {
    std::string name;
    std::string phone;
};

int main() {
    std::vector<Contact> book = {
        {"Charlie", "555-0102"},
        {"Alice", "555-0100"},
        {"Bob", "555-0101"}
    };

    // Sort alphabetically by name
    std::sort(book.begin(), book.end(), [](const Contact& a, const Contact& b) {
        return a.name < b.name;
    });

    for (const auto& c : book) {
        std::cout << c.name << ": " << c.phone << "\n";
    }
    return 0;
}

