int main() {
    std::string text = "the quick brown fox jumps over the lazy dog the dog was ready";
    std::stringstream ss(text);
    std::string word;
    std::unordered_map<std::string, int> counts;

    while (ss >> word) {
        counts[word]++;
    }

    std::cout << "Frequency of 'the': " << counts["the"] << "\n"; // 3
    std::cout << "Frequency of 'dog': " << counts["dog"] << "\n"; // 2
    return 0;
}

