#include <iostream>
#include <vector>
#include <memory>
#include <string>

class Product {
protected:
    std::string name;
    double price;
public:
    Product(std::string n, double p) : name(n), price(p) {}
    virtual ~Product() = default;
    virtual double getValue() const { return price; }
};

class DiscountedProduct : public Product {
    double discountPercent;
public:
    DiscountedProduct(std::string n, double p, double d) 
        : Product(n, p), discountPercent(d) {}
    double getValue() const override { return price * (1.0 - discountPercent / 100.0); }
};

int main() {
    std::vector<std::unique_ptr<Product>> warehouse;
    warehouse.push_back(std::make_unique<Product>("Monitor", 200.0));
    warehouse.push_back(std::make_unique<DiscountedProduct>("Keyboard", 50.0, 20.0));

    for (const auto& item : warehouse) {
        std::cout << "Item value: $" << item->getValue() << "\n";
    }
    return 0;
}

