#include <iostream>
#include <string>
#include <vector>
#include <numeric>

class Student {
    int rollNo;
    std::string name;
    std::vector<double> marks;
public:
    Student(int r, std::string n, std::vector<double> m) 
        : rollNo(r), name(n), marks(m) {}

    double average() const {
        if (marks.empty()) return 0.0;
        double sum = std::accumulate(marks.begin(), marks.end(), 0.0);
        return sum / marks.size();
    }

    void printReport() const {
        std::cout << "Student: " << name << " [#" << rollNo << "] Average: " << average() << "\n";
    }
};

int main() {
    Student s1(101, "Jane Doe", {92.0, 88.5, 95.0});
    s1.printReport();
    return 0;
}

