#include <iostream>
#include <vector>
#include <unordered_set>
using namespace std;
int main() {
    int n; if (cin >> n) {
        unordered_set<int> st;
        bool dup = false;
        for (int i = 0; i < n; i++) {
            int x; cin >> x;
            if (st.count(x)) dup = true;
            st.insert(x);
        }
        cout << (dup ? "true" : "false") << "\n";
    }
    return 0;
}

solution.c:
#include <stdio.h>
#include <stdlib.h>
int cmp(const void *a, const void *b) { return (*(int*)a - *(int*)b); }
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    int *a = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    qsort(a, n, sizeof(int), cmp);
    int dup = 0;
    for (int i = 1; i < n; i++) if (a[i] == a[i-1]) { dup = 1; break; }
    puts(dup ? "true" : "false");
    free(a);
    return 0;
}
